// Lanjut hanya pada jam/hari backup (zona waktu workflow = Asia/Jakarta). Manual = selalu.
const manual = $('Jalankan manual').isExecuted;
const now = $now.setZone($env.GENERIC_TIMEZONE || 'Asia/Jakarta');
const hour = Number($env.SB_BACKUP_HOUR ?? 2);
const freq = String($env.SB_BACKUP_FREQUENCY || 'daily').toLowerCase();
const weekday = Number($env.SB_BACKUP_WEEKDAY ?? 0); // 0 = Minggu … 6 = Sabtu
const isDay = freq !== 'weekly' || (now.weekday % 7) === weekday;
if (!manual && (now.hour !== hour || !isDay)) return [];
if (!$env.SB_BACKUP_DRIVE_FOLDER_ID) throw new Error('SB_BACKUP_DRIVE_FOLDER_ID belum diatur');
return [{ json: {
  stamp: now.toFormat('yyyy-MM-dd-HHmm'),
  date: now.toFormat('yyyy-MM-dd'),
  frequency: freq,
  include_versions: String($env.SB_BACKUP_INCLUDE_VERSIONS || '0') === '1' ? '1' : '0',
} }];

// Gabung semua halaman → satu file backup (format sama dengan endpoint & Settings restore).
const cfg = $('Jadwal?').first().json;
const users = $input.all().flatMap(i => i.json.users || []);
if (!users.length) throw new Error('Backup kosong: tidak ada user yang diekspor');
const totals = {};
for (const u of users) for (const [t, n] of Object.entries(u.counts || {})) totals[t] = (totals[t] || 0) + n;
const backup = { version: 1, format: 'second-brain-backup', exported_at: new Date().toISOString(), page: 0, next_page: null, count: users.length, users };
const text = JSON.stringify(backup);
const fileName = `second-brain-backup-${cfg.stamp}.json`;
const binary = { data: await this.helpers.prepareBinaryData(Buffer.from(text, 'utf8'), fileName, 'application/json') };
return [{ json: { fileName, users: users.length, totals, json_bytes: Buffer.byteLength(text) }, binary }];

// Catat ukuran .gz (untuk batas lampiran email) dan teruskan file apa adanya.
const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
const item = $input.first();
return [{ json: { ...item.json, gz_bytes: buf.length }, binary: item.binary }];

// Rotasi: simpan SB_BACKUP_RETENTION file terbaru (default 14), hapus sisanya.
const keep = Math.max(1, Number($env.SB_BACKUP_RETENTION || 14));
const files = $('Daftar backup').all().map(i => i.json)
  .filter(f => f.id && /^second-brain-backup-.*\.json(\.gz)?$/.test(f.name || ''))
  .sort((a, b) => String(b.createdTime || b.name).localeCompare(String(a.createdTime || a.name)));
const expired = files.slice(keep);
return expired.map(f => ({ json: { id: f.id, name: f.name } }));

// Ringkasan email + lampiran .json.gz bila ukurannya ≤ SB_BACKUP_EMAIL_ATTACH_MAX_MB.
const keep = Math.max(1, Number($env.SB_BACKUP_RETENTION || 14));
const files = $('Daftar backup').all().map(i => i.json)
  .filter(f => f.id && /^second-brain-backup-.*\.json(\.gz)?$/.test(f.name || ''))
  .sort((a, b) => String(b.createdTime || b.name).localeCompare(String(a.createdTime || a.name)));
const expired = files.slice(keep);
const meta = $('Gabung & ringkas').first().json;
const upload = $('Upload ke Google Drive').first().json;
const sized = $('Ukuran file').first();
const gz = sized.binary.data;
const gzBytes = sized.json.gz_bytes;
const maxMb = Number($env.SB_BACKUP_EMAIL_ATTACH_MAX_MB ?? 5);
const attach = maxMb > 0 && gzBytes > 0 && gzBytes <= maxMb * 1048576;
const mb = (b) => (b / 1048576).toFixed(2) + ' MB';
const rows = Object.entries(meta.totals).map(([t, n]) => `<tr><td>${t}</td><td align="right">${n}</td></tr>`).join('');
const link = upload.id ? `https://drive.google.com/file/d/${upload.id}/view` : null;
const html = `<h2>✅ Backup Second Brain berhasil</h2>
<p><b>File:</b> ${upload.name || meta.fileName + '.gz'} (${mb(gzBytes)}, JSON ${mb(meta.json_bytes)})<br>
<b>User:</b> ${meta.users}<br>${link ? `<b>Google Drive:</b> <a href="${link}">${link}</a><br>` : ''}
<b>Rotasi:</b> simpan ${keep} terbaru, ${expired.length} file lama dihapus.<br>
<b>Lampiran:</b> ${attach ? 'ya' : `tidak (lebih dari ${maxMb} MB, unduh dari Drive)`}</p>
<table border="1" cellpadding="4" cellspacing="0"><tr><th>Tabel</th><th>Baris</th></tr>${rows}</table>
<p>Pulihkan: Second Brain → Pengaturan → Backup → <i>Pulihkan JSON</i> → pilih file .json.gz.</p>`;
return [{ json: { subject: `Backup Second Brain ${meta.users} user · ${mb(gzBytes)}`, html, attach }, ...(attach ? { binary: { data: gz } } : {}) }];

// Dipanggil dari output error node mana pun di workflow ini.
const err = $json.error || {};
const msg = String(err.message || err.description || $json.message || 'Unknown error').slice(0, 800);
const node = $prevNode?.name || '-';
const when = $now.setZone($env.GENERIC_TIMEZONE || 'Asia/Jakarta').toFormat('yyyy-MM-dd HH:mm');
return [{ json: {
  text: `🚨 Backup Second Brain GAGAL\nLangkah: ${node}\nWaktu: ${when}\nPesan: ${msg}\n🔗 ${$execution.id}`,
  subject: `GAGAL: backup Second Brain ${when}`,
  html: `<h2>🚨 Backup Second Brain gagal</h2><p><b>Langkah:</b> ${node}<br><b>Waktu:</b> ${when}<br><b>Eksekusi:</b> ${$execution.id}</p><pre>${msg.replace(/[<>&]/g, c => ({'<':'&lt;','>':'&gt;','&':'&amp;'}[c]))}</pre>`,
} }];
